// Character encoding in action — verified via Node.js

// 1) ASCII values
console.log('A'.charCodeAt(0));   // 65
console.log('a'.charCodeAt(0));   // 97
console.log('0'.charCodeAt(0));   // 48

// 2) Unicode code points (codePointAt handles emoji correctly)
console.log('😀'.codePointAt(0).toString(16)); // 1f600
console.log('中'.codePointAt(0));              // 20013 (U+4E2D)

// 3) UTF-8 byte lengths via TextEncoder (Node >= 11 / all browsers)
const enc = new TextEncoder(); // always UTF-8
console.log(enc.encode('A').length);   // 1
console.log(enc.encode('©').length);   // 2
console.log(enc.encode('中').length);   // 3
console.log(enc.encode('😀').length);   // 4

// 4) JS string .length counts UTF-16 code units, not characters!
console.log('😀'.length);  // 2  <- surprises many developers

// Use Array.from to count actual characters (code points)
console.log(Array.from('😀').length); // 1

// UTF-8 leading-byte patterns (how you know the byte count)
// 0xxxxxxx              1 byte  — ASCII range U+0000..U+007F
// 110xxxxx 10xxxxxx     2 bytes — U+0080..U+07FF  (e.g. ©)
// 1110xxxx 10xxxxxx 10xxxxxx    3 bytes — U+0800..U+FFFF (e.g. 中)
// 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx  4 bytes — U+10000..U+10FFFF (e.g. 😀)

// Correctly count Unicode code points in a JS string:
function charCount(str) {
  return Array.from(str).length;
}

// Convert a code point to its UTF-8 bytes:
function toUtf8Bytes(codePoint) {
  return [...new TextEncoder().encode(String.fromCodePoint(codePoint))];
}
console.log(toUtf8Bytes(0x1F600)); // [240, 159, 152, 128]  (0xF0 0x9F 0x98 0x80)
